@@ -57,6 +57,13 @@
 @media (hover: none) {
   .oil .oil-actions { opacity: 1; transform: none; pointer-events: auto; }
 }
+/* Respect a reduced-motion preference: reveal/transition instantly, don't slide. */
+@media (prefers-reduced-motion: reduce) {
+  .oil .oil-actions,
+  .oil .oil-reset,
+  .oil .oil-lab,
+  .oil .oil-lab .oil-lab-ic { transition: none; }
+}
 .oil .oil-reset {
   display: inline-flex;
   align-items: center;
