 .oil .oil-lab:hover { border-color: var(--accent); background: var(--accent-softer); color: var(--accent); }
 .oil .oil-lab:hover .oil-lab-ic { transform: translate(1px, -1px); }
-.oil .oil-lab[aria-disabled="true"] { opacity: 0.5; pointer-events: none; }

